contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address to, uint256 depositAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        require(depositAmount > 0);
        require(address(this).balance >= depositAmount);

        c.deposit{value: depositAmount}(); if (__ESBMC_reverted()) return;

        uint256 balanceBefore = address(c).balance;

        bool migrationSucceeded;
        c.migrateTo(to); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            migrationSucceeded = false;
        } else {
            migrationSucceeded = true;
        }

        assert((migrationSucceeded && (address(c).balance == 0)) || (!migrationSucceeded && (address(c).balance == balanceBefore)));
    }

    receive() external payable {}
}

