// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Wallet c;

    function setUp() public {
        c = new Wallet();
    }

    function _run(address to, uint256 depositAmount) internal {
        depositAmount = bound(depositAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(depositAmount > 0);
        vm.assume(address(this).balance >= depositAmount);
        try c.deposit{value: depositAmount}() {} catch { return; }
        uint256 balanceBefore = address(c).balance;
        bool migrationSucceeded;
        try c.migrateTo(to) {
            migrationSucceeded = true;
        } catch {
            migrationSucceeded = false;
        }
        assertTrue((migrationSucceeded && (address(c).balance == 0)) || (!migrationSucceeded && (address(c).balance == balanceBefore)));
    }

    function testFuzz_run(address to, uint256 depositAmount) public {
        vm.assume(to.code.length == 0 && uint160(to) > 0xffff && to != address(this) && to != address(c) && to != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && to != 0x000000000000000000636F6e736F6c652e6c6f67 && to != 0x4e59b44847b379578588920cA78FbF26c0B4956C && to != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(to, depositAmount);
    }

    receive() external payable {}
}
